// B1 Config. dry_run=true usa ideias mock e não grava nada.
const inp = $input.first()?.json || {};
return [{ json: {
  dry_run: inp.dry_run !== false,
  max_pieces: inp.max_pieces || 3,
  format: inp.format || 'short_video',
  platforms: inp.platforms || ['instagram', 'tiktok', 'youtube', 'facebook', 'linkedin'], // PENDENTE: Thiago escolher os canais
  audience: inp.audience || 'Small local businesses and tradies on the Gold Coast / SE Queensland (English, AU) — PENDENTE confirmar',
} }];

// B1b Mock de ideias para dry-run (sem Supabase)
return [
  { json: { id: null, source: 'google_news', title: 'Boyd Group Has AI Agents Booking Repairs. Claims Paperwork Is Next.', summary: '', score: 46 } },
  { json: { id: null, source: 'hacker_news', title: 'United Airlines bans AI agents from booking flights on behalf of travelers', summary: '', score: 69 } },
];

// B2 Seleciona ideias e monta o prompt (para o LLM) + plano de canais. Sem rede.
// Entrada: itens de mkt_content_ideas (via Supabase) ou mock quando dry_run.
const COMPANY_ID = '4a617a32-8493-4bd1-a9ab-12f5edf2055a';
const cfg = $('Config').first().json;
const ideas = $input.all().map(i => i.json).flatMap(j => Array.isArray(j.ideas) ? j.ideas : [j]).filter(j => j && j.title);
const BRAND = {
  name: 'Cytron AI', site: 'https://cytronai.com',
  offer: 'AI automation for small businesses: AI receptionist / missed-call text-back, lead capture and follow-up, bookings, quotes and back-office workflows (n8n).',
  audience: cfg.audience, voice: 'Plain-English, practical, local (Australian spelling), confident but no hype, no fake numbers, one clear CTA.',
  cta: 'Book a free 15-min automation audit',
};
const LIMITS = { instagram: 2200, tiktok: 2200, youtube: 100, facebook: 5000, linkedin: 3000, threads: 500, twitter: 280 };
const out = ideas.slice(0, cfg.max_pieces).map((idea, n) => {
  const slug = (idea.title || 'post').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40);
  const utm_campaign = `mkt_${new Date(Date.now() + 10 * 36e5).toISOString().slice(0, 10).replace(/-/g, '')}_${slug}`.slice(0, 80);
  const prompt = [
    `You are the content writer for ${BRAND.name} (${BRAND.site}). Offer: ${BRAND.offer}`,
    `Audience: ${BRAND.audience}. Voice: ${BRAND.voice}`,
    `Trend/idea (source ${idea.source}): "${idea.title}". ${idea.summary || ''}`,
    `Write ONE ${cfg.format} for: ${cfg.platforms.join(', ')}. Return strict JSON:`,
    `{"title":"","hook":"<=12 words","script":"30-45s voiceover, 3 beats: problem, how AI automation fixes it, CTA","caption":"","hashtags":["max 6"],"cta":"${BRAND.cta}","variants":{"<platform>":{"text":"","title":""}}}`,
    `Respect limits: ${JSON.stringify(LIMITS)}. Never invent client results or statistics.`,
  ].join('\n');
  return { json: { company_id: COMPANY_ID, idea, prompt, utm_campaign, platforms: cfg.platforms, format: cfg.format, limits: LIMITS, brand: BRAND, n } };
});
return out;

// B4 Gerador SEM LLM (grátis, determinístico) — usado enquanto não há chave paga.
// Se o nó Gemini rodar e devolver JSON válido, ele tem prioridade.
const preps = $('Prepare prompt').all().map(i => i.json);
const llm = $input.all().map(i => i.json);
const pick = (arr, n) => arr[n % arr.length];
const HOOKS = ['Still losing jobs to missed calls?', 'Your competitors just hired an AI receptionist.', 'This is what AI actually does for a small business.', 'Stop doing this by hand.'];
return preps.map((p, i) => {
  let g = null, generator = 'template_v1';
  try { const t = llm[i]?.candidates?.[0]?.content?.parts?.[0]?.text; if (t) { g = JSON.parse(t.replace(/^```json|```$/g, '').trim()); generator = 'gemini'; } } catch (e) { g = null; }
  const idea = p.idea; const link = `${p.brand.site}/?utm_source={platform}&utm_medium=social&utm_campaign=${p.utm_campaign}`;
  if (!g) {
    const hook = pick(HOOKS, p.n);
    g = {
      title: `AI for small business: ${idea.title}`.slice(0, 95), hook,
      script: `${hook}\nIn the news this week: ${idea.title}.\nWhat it means for you: the same AI that big companies use can answer your calls, reply to enquiries in seconds and book jobs while you're on the tools.\n${p.brand.cta} — link in bio.`,
      caption: `${hook}\n\n${idea.title} — here's the practical version for local businesses: answer every enquiry, follow up every lead, book the job. No new staff.\n\n${p.brand.cta} 👉 {link}`,
      hashtags: ['#smallbusiness', '#aiautomation', '#goldcoast', '#tradies', '#australianbusiness', '#cytronai'], cta: p.brand.cta, variants: {},
    };
  }
  const variants = {};
  for (const pl of p.platforms) {
    const v = (g.variants && g.variants[pl]) || {};
    let text = (v.text || g.caption || '').replace('{link}', link.replace('{platform}', pl));
    if (pl !== 'youtube' && !text.includes('#')) text += '\n\n' + (g.hashtags || []).slice(0, 6).join(' ');
    variants[pl] = { text: text.slice(0, p.limits[pl] || 2200), title: (v.title || g.title || '').slice(0, pl === 'youtube' ? 100 : 150), link: link.replace('{platform}', pl) };
  }
  return { json: { company_id: p.company_id, idea_id: idea.id || null, format: p.format, title: g.title, hook: g.hook, script: g.script,
    caption: (g.caption || '').replace('{link}', link.replace('{platform}', 'instagram')), hashtags: g.hashtags || [], cta: g.cta, target_platforms: p.platforms,
    platform_variants: variants, media_urls: [], utm_campaign: p.utm_campaign, status: 'pending_approval', generator,
    generator_meta: { prompt_chars: p.prompt.length, media: 'PENDENTE: vídeo Veo3 / voz ElevenLabs / design Fox' } } };
});
